import{_ as e,o as i,c as a,a2 as r}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"Multi-provider mock pattern","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/multi-provider-mock.md","filePath":"concepts/multi-provider-mock.md"}'),d={name:"concepts/multi-provider-mock.md"};function o(s,t,l,n,p,c){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="multi-provider-mock-pattern" tabindex="-1">Multi-provider mock pattern <a class="header-anchor" href="#multi-provider-mock-pattern" aria-label="Permalink to &quot;Multi-provider mock pattern&quot;">​</a></h1><p>kiwa は SaaS domain (email / webhook / feature-flag / upload / notification / vector / graphql / trpc / i18n / workflow / auth / cache / queue / search / streaming / ai-llm / realtime / payment / orm / agent / mcp) の各 lib で「複数 provider を統一 interface で mock する」 pattern を採用する。 本 doc はその設計思想 + 実装 SSOT。</p><h2 id="why-なぜ統一-interface-か" tabindex="-1">Why (なぜ統一 interface か) <a class="header-anchor" href="#why-なぜ統一-interface-か" aria-label="Permalink to &quot;Why (なぜ統一 interface か)&quot;">​</a></h2><p>SaaS app は開発中に provider 変更する。 例:</p><ul><li>MVP は Resend で email 送信、 scale 後 SendGrid に移行</li><li>Pinecone で RAG prototype、 self-host 段階で pgvector に移行</li><li>LaunchDarkly で feature flag、 cost 削減で GrowthBook に移行</li></ul><p>test を provider ごとに書き直すと、 移行 cost が線形に増える。 kiwa は「provider 別差 (id prefix / signature encoding / event key 名) を吸収した抽象」 を提供、 provider 変更 = 1 引数変更 (<code>provider: &#39;resend&#39;</code> → <code>provider: &#39;sendgrid&#39;</code>) で同じ test が通る。</p><h2 id="実装-pattern-email-lib-ssot" tabindex="-1">実装 pattern (email lib SSOT) <a class="header-anchor" href="#実装-pattern-email-lib-ssot" aria-label="Permalink to &quot;実装 pattern (email lib SSOT)&quot;">​</a></h2><p><code>packages/email/src/client.ts</code> を SSOT として、 全 SaaS lib で以下 5 要素を統一する。</p><h3 id="_1-create-client-options-client" tabindex="-1">1. <code>create*Client(options): *Client</code> <a class="header-anchor" href="#_1-create-client-options-client" aria-label="Permalink to &quot;1. `create*Client(options): *Client`&quot;">​</a></h3><p>provider を string literal type で受け取る factory。 全 lib で <code>provider</code> field 必須、 default は最 popular な provider (email = resend / vector = pinecone 等)。</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createEmailClient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">options</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">provider</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;resend&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sendgrid&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;postmark&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ses&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EmailClient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="_2-provider-type-string-union" tabindex="-1">2. <code>Provider</code> type = string union <a class="header-anchor" href="#_2-provider-type-string-union" aria-label="Permalink to &quot;2. `Provider` type = string union&quot;">​</a></h3><p><code>type EmailProvider = &#39;resend&#39; | &#39;sendgrid&#39; | &#39;postmark&#39; | &#39;ses&#39;</code>。 lib の中心 type、 全 API がこれを引数に取る。</p><h3 id="_3-provider-別差の吸収経路" tabindex="-1">3. Provider 別差の吸収経路 <a class="header-anchor" href="#_3-provider-別差の吸収経路" aria-label="Permalink to &quot;3. Provider 別差の吸収経路&quot;">​</a></h3><ul><li><strong>id prefix</strong> = 各 provider で異なる id format (Resend = <code>re-N</code> / SendGrid = <code>sg-N</code> / SES = <code>ses-N</code>) を internal mapping で自動割振り</li><li><strong>signature encoding</strong> = SES = HMAC-SHA1 / 他 = HMAC-SHA256、 SendGrid = base64 / 他 = hex。 <code>verifyWebhookSignature</code> 内で provider 分岐して自動選択</li><li><strong>event key 名</strong> = Resend = <code>type</code> / SendGrid = <code>event</code> / Postmark = <code>RecordType</code> / SES = <code>eventType</code>。 <code>parseDeliveryEvent</code> 内で mapping table を持ち統一 shape に normalize</li></ul><h3 id="_4-list-sentrecord-系-introspection-api" tabindex="-1">4. <code>list*(): SentRecord[]</code> 系 introspection API <a class="header-anchor" href="#_4-list-sentrecord-系-introspection-api" aria-label="Permalink to &quot;4. `list*(): SentRecord[]` 系 introspection API&quot;">​</a></h3><p>send / dispatch した record を全件返す method、 test で「N 件送信された」「特定 recipient 宛」 を assertion する主経路。 provider 経由を意識せず統一 assertion が書ける。</p><h3 id="_5-clear-method" tabindex="-1">5. <code>clear()</code> method <a class="header-anchor" href="#_5-clear-method" aria-label="Permalink to &quot;5. `clear()` method&quot;">​</a></h3><p>test 間で state を reset、 <code>beforeEach(() =&gt; client.clear())</code> pattern で test 隔離を保証。</p><h2 id="fidelity-vs-mock-の哲学" tabindex="-1">Fidelity vs Mock の哲学 <a class="header-anchor" href="#fidelity-vs-mock-の哲学" aria-label="Permalink to &quot;Fidelity vs Mock の哲学&quot;">​</a></h2><p>本 pattern は「real provider の SDK と同じ signature で叩ける mock」 を提供、 real provider ↔ mock 間の behavior fidelity は <code>@kiwa-lab/quality-metrics</code> の <code>assertFidelity</code> で verify する。</p><ul><li>mock 単独 test = <code>packages/*/tests/skill/*.skill.test.ts</code> (fast、 CI default で走る)</li><li>mock vs real reference impl = <code>packages/*/tests/fidelity/*.fidelity.test.ts</code> (mock が仕様通り動くか)</li><li>mock vs real provider = <code>packages/*/tests/fidelity/*.real.fidelity.test.ts</code> (env-gate <code>KIWA_MODE=real</code>、 opt-in で走る)</li></ul><p>3 段 fidelity chain で「mock が real provider の behavior を再現している」 confidence を build up する。</p><h2 id="適用-lib-一覧" tabindex="-1">適用 lib 一覧 <a class="header-anchor" href="#適用-lib-一覧" aria-label="Permalink to &quot;適用 lib 一覧&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分類</th><th>lib</th><th>provider 数</th></tr></thead><tbody><tr><td>email</td><td>@kiwa-lab/email</td><td>4 (Resend / SendGrid / Postmark / SES)</td></tr><tr><td>webhook</td><td>@kiwa-lab/webhook</td><td>4 (Stripe / GitHub / Slack / Twilio)</td></tr><tr><td>feature-flag</td><td>@kiwa-lab/feature-flag</td><td>4 (GrowthBook / LaunchDarkly / PostHog / Unleash)</td></tr><tr><td>upload</td><td>@kiwa-lab/upload</td><td>4 (S3 / GCS / R2 / Cloudinary)</td></tr><tr><td>notification</td><td>@kiwa-lab/notification</td><td>5 (FCM / APNs / Twilio / SNS / inapp)</td></tr><tr><td>vector</td><td>@kiwa-lab/vector</td><td>4 (Pinecone / Weaviate / Qdrant / pgvector)</td></tr><tr><td>graphql</td><td>@kiwa-lab/graphql</td><td>4 (Apollo / Yoga / urql / Relay)</td></tr><tr><td>i18n</td><td>@kiwa-lab/i18n</td><td>4 (next-intl / vue-i18n / react-i18next / Lingui)</td></tr><tr><td>workflow</td><td>@kiwa-lab/workflow</td><td>4 (Temporal / Inngest / Trigger.dev / Step Functions)</td></tr><tr><td>form</td><td>@kiwa-lab/form</td><td>4 (React Hook Form / Zod / Formik / Conform)</td></tr><tr><td>state</td><td>@kiwa-lab/state</td><td>5 (Zustand / Redux / Jotai / Valtio / MobX)</td></tr><tr><td>query</td><td>@kiwa-lab/query</td><td>4 (TanStack Query / SWR / urql / Apollo Client)</td></tr><tr><td>date</td><td>@kiwa-lab/date</td><td>4 (date-fns / dayjs / Luxon / Temporal)</td></tr><tr><td>chart</td><td>@kiwa-lab/chart</td><td>4 (Recharts / Chart.js / D3 / Visx)</td></tr><tr><td>migration</td><td>@kiwa-lab/migration</td><td>4 (Prisma / Drizzle / Kysely / Knex)</td></tr><tr><td>websocket</td><td>@kiwa-lab/websocket</td><td>4 (ws / uWebSockets / Socket.IO / Colyseus)</td></tr><tr><td>grpc</td><td>@kiwa-lab/grpc</td><td>4 (grpc-js / nice-grpc / twirp / connect-rpc)</td></tr><tr><td>python</td><td>@kiwa-lab/python</td><td>4 (Django / Flask / FastAPI / Starlette)</td></tr><tr><td>ruby</td><td>@kiwa-lab/ruby</td><td>4 (Rails / Sinatra / Roda / Hanami)</td></tr><tr><td>rust-lib</td><td>@kiwa-lab/rust-lib</td><td>4 (axum / actix-web / tower-http / rocket)</td></tr><tr><td>go-lib</td><td>@kiwa-lab/go-lib</td><td>4 (gin / echo / fiber / chi)</td></tr></tbody></table><p>計 22 lib で 5 primitive の統一 pattern を採用。</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./lib-composition">Lib composition pattern</a> — 複数 lib を組合わせて real app test を書く</li><li><a href="./../api/test-taxonomy-guide">Test taxonomy guide</a> — 4 category test の統一分類</li></ul>',28)])])}const m=e(d,[["render",o]]);export{k as __pageData,m as default};
